CREATE TABLE "conversations" ("id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"last_response_id" TEXT,"created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"updated_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"client_day" TEXT,CONSTRAINT "conversations_pkey" PRIMARY KEY (id),CONSTRAINT "conversations_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id));
CREATE INDEX conversations_user_client_day_updated_idx ON conversations (user_id, client_day, updated_at DESC) WHERE (client_day IS NOT NULL);
CREATE TABLE "feedback" ("id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"content" TEXT NOT NULL,"category" TEXT,"context" TEXT,"created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),CONSTRAINT "feedback_pkey" PRIMARY KEY (id),CONSTRAINT "feedback_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE "iap_transactions" ("transaction_id" TEXT NOT NULL,"original_transaction_id" TEXT,"user_id" TEXT NOT NULL,"product_id" TEXT NOT NULL,"credits" INTEGER NOT NULL,"subscription_expires_at" TEXT,"created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),CONSTRAINT "iap_transactions_pkey" PRIMARY KEY (transaction_id),CONSTRAINT "iap_transactions_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id));
CREATE INDEX iap_transactions_user_created_idx ON iap_transactions (user_id, created_at DESC);
CREATE TABLE "item_records" ("id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"item_id" TEXT,"position_id" TEXT,"media_asset_id" TEXT,"container" TEXT,"note" TEXT,"recorded_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),CONSTRAINT "item_records_item_id_fkey" FOREIGN KEY (item_id) REFERENCES items(id),CONSTRAINT "item_records_media_asset_id_fkey" FOREIGN KEY (media_asset_id) REFERENCES media_assets(id),CONSTRAINT "item_records_pkey" PRIMARY KEY (id),CONSTRAINT "item_records_position_id_fkey" FOREIGN KEY (position_id) REFERENCES positions(id),CONSTRAINT "item_records_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id));
CREATE INDEX idx_item_records_user ON item_records (user_id, recorded_at DESC);
CREATE INDEX idx_item_records_item ON item_records (item_id, recorded_at DESC);
CREATE INDEX idx_item_records_position ON item_records (position_id, recorded_at DESC);
CREATE TABLE "items" ("id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),CONSTRAINT "items_pkey" PRIMARY KEY (id),CONSTRAINT "items_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id));
CREATE INDEX idx_items_user ON items (user_id);
CREATE INDEX idx_items_name ON items (user_id, name);
CREATE TABLE "media_assets" ("id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"position_id" TEXT,"blob_url" TEXT NOT NULL,"content_type" TEXT NOT NULL,"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"thumbnail_url" TEXT,CONSTRAINT "media_assets_pkey" PRIMARY KEY (id),CONSTRAINT "media_assets_position_id_fkey" FOREIGN KEY (position_id) REFERENCES positions(id),CONSTRAINT "media_assets_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE "messages" ("id" TEXT NOT NULL,"conversation_id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"role" TEXT NOT NULL,"type" TEXT NOT NULL,"content" TEXT,"blob_url" TEXT,"suggestion" TEXT,"media_asset_id" TEXT,"confirmed" INTEGER DEFAULT 0,"created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"source" TEXT DEFAULT 'assistant',"steps" TEXT,CONSTRAINT "messages_conversation_id_fkey" FOREIGN KEY (conversation_id) REFERENCES conversations(id),CONSTRAINT "messages_pkey" PRIMARY KEY (id));
CREATE TABLE "positions" ("id" TEXT NOT NULL,"space_id" TEXT,"user_id" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),CONSTRAINT "positions_pkey" PRIMARY KEY (id),CONSTRAINT "positions_space_id_fkey" FOREIGN KEY (space_id) REFERENCES spaces(id) ON DELETE CASCADE,CONSTRAINT "positions_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id));
CREATE INDEX idx_positions_space ON positions (space_id);
CREATE TABLE "reward_events" ("id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"source" TEXT NOT NULL,"credits" INTEGER NOT NULL,"related_user_id" TEXT,"created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),CONSTRAINT "reward_events_pkey" PRIMARY KEY (id),CONSTRAINT "reward_events_related_user_id_fkey" FOREIGN KEY (related_user_id) REFERENCES users(id),CONSTRAINT "reward_events_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id));
CREATE UNIQUE INDEX reward_events_welcome_unique ON reward_events (user_id, source) WHERE (source = 'welcome');
CREATE UNIQUE INDEX reward_events_invite_redeemee_unique ON reward_events (user_id, source) WHERE (source = 'invite_redeemee');
CREATE TABLE "spaces" ("id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"name" TEXT NOT NULL,"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),CONSTRAINT "spaces_pkey" PRIMARY KEY (id),CONSTRAINT "spaces_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id));
CREATE INDEX idx_spaces_user ON spaces (user_id);
CREATE TABLE "usage_daily" ("user_id" TEXT NOT NULL,"day" TEXT NOT NULL,"query_count" INTEGER NOT NULL DEFAULT 0,"analyze_count" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "usage_daily_pkey" PRIMARY KEY (user_id, day),CONSTRAINT "usage_daily_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE "users" ("id" TEXT NOT NULL,"email" TEXT,"name" TEXT,"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"apple_user_id" TEXT,"free_credits" INTEGER NOT NULL DEFAULT 3,"paid_credits" INTEGER NOT NULL DEFAULT 0,"subscription_expires_at" TEXT,"invite_code" TEXT,"welcome_claimed_at" TEXT,"referred_by_user_id" TEXT,"invite_redeemed_at" TEXT,"subscription_product_id" TEXT,"last_ip" TEXT,"last_language" TEXT,"last_seen_at" TEXT,CONSTRAINT "users_apple_user_id_key" UNIQUE (apple_user_id),CONSTRAINT "users_email_key" UNIQUE (email),CONSTRAINT "users_pkey" PRIMARY KEY (id),CONSTRAINT "users_referred_by_user_id_fkey" FOREIGN KEY (referred_by_user_id) REFERENCES users(id));
CREATE UNIQUE INDEX users_apple_user_id_unique ON users (apple_user_id) WHERE (apple_user_id IS NOT NULL);
CREATE UNIQUE INDEX users_invite_code_unique ON users (invite_code) WHERE (invite_code IS NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS cf_apple_id_unique ON users(apple_user_id);
ALTER TABLE iap_transactions ADD COLUMN grant_token TEXT;
ALTER TABLE media_assets ADD COLUMN ai_media_url TEXT;
CREATE TABLE membership_grants(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE confirmations(user_id TEXT NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,token TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(user_id,request_key));
CREATE TABLE jobs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,credit_type TEXT,quota_day TEXT NOT NULL,input_key TEXT,result TEXT,settle_token TEXT,refunded INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(user_id,request_key));
CREATE INDEX jobs_status_updated ON jobs(status,updated_at);
